"use client";

import React, { useState, useEffect, useRef } from 'react';
import { supabase } from '@/lib/supabase';
import { 
  Layers, 
  Plus, 
  Trash2,
  X, 
  FolderTree,
  Image as ImageIcon,
  Loader2,
  AlertCircle,
  Sparkles,
  CheckCircle2,
  ToggleLeft,
  ToggleRight
} from 'lucide-react';

// Client-Side Canvas WebP Image Compressor
const compressAndConvertToWebP = (file: File, maxWidth = 800, quality = 0.82): Promise<File> => {
  return new Promise((resolve) => {
    if (!file.type.startsWith('image/')) {
      return resolve(file);
    }

    const reader = new FileReader();
    reader.readAsDataURL(file);
    reader.onload = (event) => {
      const img = new Image();
      img.src = event.target?.result as string;
      img.onload = () => {
        const canvas = document.createElement('canvas');
        let width = img.width;
        let height = img.height;

        if (width > maxWidth) {
          height = Math.round((height * maxWidth) / width);
          width = maxWidth;
        }

        canvas.width = width;
        canvas.height = height;

        const ctx = canvas.getContext('2d');
        ctx?.drawImage(img, 0, 0, width, height);

        canvas.toBlob(
          (blob) => {
            if (blob) {
              const cleanName = file.name.substring(0, file.name.lastIndexOf('.')) || 'category';
              const webpFileName = `${cleanName}_${Date.now()}.webp`;
              const webpFile = new File([blob], webpFileName, { type: "image/webp" });
              resolve(webpFile);
            } else {
              resolve(file);
            }
          },
          "image/webp",
          quality
        );
      };
      img.onerror = () => resolve(file);
    };
    reader.onerror = () => resolve(file);
  });
};

export default function CategoryManager() {
  const [categories, setCategories] = useState<any[]>([]);
  
  const [newCat, setNewCat] = useState("");
  const [imageFile, setImageFile] = useState<File | null>(null);
  const [isUploading, setIsUploading] = useState(false);
  const [compressing, setCompressing] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);

  const fetchCategories = async () => {
    const { data } = await supabase.from('categories').select('*').order('name');
    if (data) setCategories(data);
  };

  useEffect(() => {
    fetchCategories();
  }, []);

  const handleImageSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setCompressing(true);
    try {
      const webpFile = await compressAndConvertToWebP(file);
      setImageFile(webpFile);
    } catch (err) {
      console.error('Image compression error:', err);
      setImageFile(file);
    } finally {
      setCompressing(false);
    }
  };

  const handleAddCategory = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newCat.trim()) return alert("Please enter a category name.");

    // MANDATORY IMAGE UPLOAD GUARD
    if (!imageFile) {
      return alert("Please upload a category photo before saving.");
    }

    setIsUploading(true);

    try {
        let imageUrl = "";

        const fileName = `${Date.now()}_${Math.random().toString(36).substring(2)}.webp`;
        const { error: uploadError } = await supabase.storage
          .from('categories')
          .upload(fileName, imageFile, { contentType: 'image/webp' });

        if (uploadError) throw uploadError;

        const { data: urlData } = supabase.storage
          .from('categories')
          .getPublicUrl(fileName);

        imageUrl = urlData.publicUrl;

        const { error } = await supabase.from('categories').insert({
          name: newCat.trim(),
          image_url: imageUrl,
          status: 'active',
        });

        if (error) throw error;

        setNewCat("");
        setImageFile(null);
        if (fileInputRef.current) fileInputRef.current.value = "";
        alert("Category & WebP Photo Uploaded Successfully!");
        fetchCategories();
    } catch (error: any) {
        console.error("Error adding category:", error);
        alert("Failed to add category: " + (error.message || "Upload failed"));
    } finally {
        setIsUploading(false);
    }
  };

  const handleToggleCategoryStatus = async (catId: string, currentStatus: string) => {
    const newStatus = currentStatus === 'active' ? 'inactive' : 'active';
    try {
      const { error } = await supabase
        .from('categories')
        .update({ status: newStatus })
        .eq('id', catId);

      if (!error) {
        fetchCategories();
      } else {
        alert('Failed to update status: ' + error.message);
      }
    } catch (err) {
      console.error('Error toggling category status:', err);
    }
  };

  const handleDeleteCategory = async (catId: string) => {
    if(!confirm("Are you sure? This will delete the category.")) return;

    try {
      const { error } = await supabase.from('categories').delete().eq('id', catId);
      if (!error) fetchCategories();
    } catch (error) {
      console.error("Error deleting category:", error);
      alert("Failed to delete category");
    }
  };

  const triggerFileSelect = () => fileInputRef.current?.click();

  return (
    <div className="space-y-8 p-6 max-w-[1600px] mx-auto">
      
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <div className="flex items-center gap-2">
            <h1 className="text-2xl font-black text-gray-900 tracking-tight flex items-center gap-3">
              <Layers className="text-emerald-800" />
              Category Management
            </h1>
            <span className="text-[10px] font-black uppercase bg-emerald-100 text-emerald-800 px-2.5 py-0.5 rounded-full border border-emerald-300">
              ⚡ Enable/Disable Control
            </span>
          </div>
          <p className="text-xs text-gray-500 mt-1">
            Toggle category visibility on the customer storefront with 1-tap Enable / Disable controls.
          </p>
        </div>
      </div>

      <div className="bg-white p-5 rounded-2xl border border-gray-200 shadow-sm max-w-3xl">
        <form onSubmit={handleAddCategory} className="flex flex-col sm:flex-row items-stretch sm:items-center gap-3">
          
          <div className="hidden sm:flex items-center justify-center w-10 h-10 rounded-2xl bg-amber-400 text-emerald-950 shrink-0 font-black shadow-sm">
            <FolderTree size={20} />
          </div>

          <input
            required
            value={newCat}
            onChange={(e) => setNewCat(e.target.value)}
            placeholder="Category name (e.g. Fresh Fish & Seafood)..."
            className="flex-1 w-full py-2.5 px-4 text-xs font-bold text-gray-900 placeholder:text-gray-400 bg-gray-50 rounded-xl border border-gray-200 focus:bg-white focus:border-amber-400 focus:outline-none transition-all"
          />

          <div className="flex items-center gap-2 w-full sm:w-auto">
             <input 
                type="file" 
                ref={fileInputRef}
                onChange={handleImageSelect}
                className="hidden"
                accept="image/*"
             />
             
             {compressing ? (
                <button type="button" disabled className="px-4 py-2.5 bg-gray-100 text-gray-400 rounded-xl text-xs font-bold flex items-center gap-1.5">
                  <Loader2 size={14} className="animate-spin text-amber-500" /> WebP...
                </button>
             ) : imageFile ? (
                <button 
                    type="button" 
                    onClick={triggerFileSelect}
                    className="flex-1 sm:flex-none flex items-center gap-2 bg-emerald-50 px-3.5 py-2.5 rounded-xl text-xs font-black text-emerald-800 border border-emerald-300 hover:bg-emerald-100 transition-colors"
                >
                    <CheckCircle2 size={14} className="text-emerald-600" />
                    <span className="truncate max-w-[100px]">{imageFile.name}</span>
                </button>
             ) : (
                <button 
                    type="button" 
                    onClick={triggerFileSelect}
                    className="flex-1 sm:flex-none flex items-center justify-center gap-2 px-4 py-2.5 text-amber-900 bg-amber-100 hover:bg-amber-200 border border-amber-300 rounded-xl transition-colors text-xs font-black uppercase tracking-wider whitespace-nowrap"
                >
                    <ImageIcon size={16} />
                    <span>Upload Image *</span>
                </button>
             )}

            <button
                type="submit" 
                disabled={!newCat.trim() || !imageFile || isUploading || compressing}
                className="flex-1 sm:flex-none bg-emerald-800 hover:bg-emerald-900 text-amber-300 px-6 py-2.5 rounded-xl text-xs font-black uppercase tracking-wider disabled:opacity-50 disabled:cursor-not-allowed transition-all flex items-center justify-center gap-2 min-w-[100px] shadow-sm"
            >
                {isUploading ? (
                    <Loader2 size={16} className="animate-spin" />
                ) : (
                    <>
                        <Plus size={16} />
                        Add Category
                    </>
                )}
            </button>
          </div>
        </form>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-5">
        {categories.map((cat) => {
          const isActive = (cat.status || 'active') === 'active';

          return (
            <div key={cat.id} className={`bg-white border rounded-2xl flex flex-col shadow-sm hover:shadow-md transition-all group overflow-hidden ${
              isActive ? 'border-gray-200' : 'border-rose-200 bg-rose-50/20'
            }`}>

              <div className="p-4 border-b border-gray-100 flex justify-between items-center bg-gray-50/60">
                <div className="flex gap-3.5 items-center">
                  <div className="h-14 w-14 rounded-2xl bg-white border border-gray-200 p-0.5 flex-shrink-0 shadow-sm overflow-hidden">
                      {cat.image_url ? (
                          <img src={cat.image_url} alt={cat.name} className="h-full w-full object-cover rounded-xl" />
                      ) : (
                          <div className="h-full w-full flex items-center justify-center text-gray-300 bg-gray-50 rounded-xl">
                              <ImageIcon size={20} />
                          </div>
                      )}
                  </div>

                  <div>
                    <h3 className="text-sm font-black text-gray-900">{cat.name}</h3>
                    <span className={`text-[10px] font-bold uppercase tracking-wider px-2 py-0.5 rounded-full border mt-1 inline-block ${
                      isActive ? 'bg-emerald-50 text-emerald-800 border-emerald-200' : 'bg-rose-50 text-rose-700 border-rose-200'
                    }`}>
                      {isActive ? 'Active on Storefront' : 'Hidden from Storefront'}
                    </span>
                  </div>
                </div>

                <div className="flex items-center gap-1">
                  <button
                    onClick={() => handleToggleCategoryStatus(cat.id, cat.status || 'active')}
                    className={`px-3 py-1.5 rounded-xl text-[10px] font-black uppercase tracking-wider border transition-all flex items-center gap-1.5 ${
                      isActive ? 'bg-emerald-100 text-emerald-900 border-emerald-300 hover:bg-emerald-200' : 'bg-rose-100 text-rose-900 border-rose-300 hover:bg-rose-200'
                    }`}
                    title={isActive ? "Disable Category" : "Enable Category"}
                  >
                    {isActive ? <ToggleRight size={16} className="text-emerald-700" /> : <ToggleLeft size={16} className="text-rose-600" />}
                    <span>{isActive ? 'Active' : 'Disabled'}</span>
                  </button>

                  <button
                    onClick={() => handleDeleteCategory(cat.id)}
                    className="text-gray-400 hover:text-rose-600 p-2 hover:bg-rose-50 rounded-xl transition-colors"
                    title="Delete Category"
                  >
                    <Trash2 size={16} />
                  </button>
                </div>

              </div>

            </div>
          );
        })}
      </div>
    </div>
  );
}
